import{_ as t,o as d,c as o,a3 as c}from"./chunks/framework.DAK02U1-.js";const f=JSON.parse('{"title":"命令行概览","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"命令行概览 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/cli/overview"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/cli/overview"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/overview"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/overview"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/overview"}]]},"headers":[],"relativePath":"zh/clice/cli/overview.md","filePath":"zh/clice/cli/overview.md","lastUpdated":1791170993000}'),r={name:"zh/clice/cli/overview.md"};function a(i,e,l,n,h,s){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="命令行概览" tabindex="-1">命令行概览 <a class="header-anchor" href="#命令行概览" aria-label="Permalink to &quot;命令行概览&quot;">​</a></h1><p>clice 只有一个二进制。编辑器启动 <code>clice serve</code> 并通过 LSP 与它通信；其余子命令在终端里驱动同一个引擎，共用它的编译数据库处理、缓存和索引。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>页面</th></tr></thead><tbody><tr><td><code>serve</code></td><td>启动语言服务器。编辑器会替你启动，见编辑器设置。</td><td><a href="./../guide/editors">editors</a></td></tr><tr><td><code>lint</code></td><td>用 worker 池对每个翻译单元运行 clang-tidy。</td><td><a href="./lint">lint</a></td></tr><tr><td><code>index</code></td><td>提前为工作区建立索引，让服务器热启动。</td><td><a href="./">index</a></td></tr><tr><td><code>format</code></td><td>用 clang-format 格式化工作区中的文件。</td><td><a href="./format">format</a></td></tr><tr><td><code>inspect</code></td><td>对源文件运行某一项功能，把原始结果打印成 JSON。</td><td></td></tr><tr><td><code>query</code></td><td>向持久化索引查询符号、引用、调用图和文件。</td><td><a href="./query">query</a></td></tr><tr><td><code>refactor</code></td><td>依据持久化索引在整个工作区重命名一个符号。</td><td><a href="./refactor">refactor</a></td></tr><tr><td><code>analyze</code></td><td>报告重构所需的事实，例如模块依赖和循环依赖。</td><td><a href="./analyze">analyze</a></td></tr><tr><td><code>modulize</code></td><td>在头文件之上把第三方库封装成 C++20 模块。</td><td><a href="./modulize">modulize</a></td></tr></tbody></table><p><code>inspect</code> 现在已可使用但还没有页面，选项通过 <code>clice inspect --help</code> 查看。</p><p><code>serve</code>、<code>index</code>、<code>lint</code>、<code>format</code>、<code>inspect</code>、<code>query</code>、<code>refactor</code>、<code>analyze</code> 和 <code>modulize</code> 都接受 <code>--configuration &lt;tag&gt;</code>，为本次运行固定构建配置，其优先级高于编辑器持久化的选择；参见<a href="./../guide/configuration#switching-configurations">切换配置</a>。</p>',5)])])}const m=t(r,[["render",a]]);export{f as __pageData,m as default};
